def G(t):
    R=[("«isolated incidents», тобто поодинокими,","поодинокими інцидентами"),("в TikTok","у Тік-Тоці"),("у TikTok","у Тік-Тоці"),
       ("Live Dictation","Лайв Диктейшн"),("ChatGPT","Чат Джі-Пі-Ті"),("Data Controls","Дейта Контролс"),("OpenAI","Оупен Ей-Ай"),
       ("Meta Muse","Мета М'юз"),("Muse","М'юз"),("Meta","Мета"),("Reuters","Рейтер"),("AI Now","Ей-Ай Нау"),("Airbnb","Ербіенбі"),
       ("Wells Fargo","Веллс Фарго"),("Wired","Вайред"),("Amazon","Амазон"),("TikTok","Тік-Ток"),("Digital Wellness Lab","Діджитал Веллнес Леб"),("Gallup","Геллап"),
       ("HUDOC","Худок"),("arXiv","Аркайв"),("Signal","Сігнал"),("Android","Андроїд"),("iPhone","Айфон"),("Apple","Еппл"),("Mac","Мак"),("iOS","Ай-Оу-Ес"),
       ("FCA","еф-сі-ей"),("ФБР","еф-бе-ер"),("ООН","о-о-ен"),("ІТ","ай-ті"),("США","Сполучених Штатів")]  # «США» в тексті — лише в родовому відмінку
    for a,b in R: t=t.replace(a,b)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("без ШІ","без штучного інтелекту"),("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("на ШІ","на штучний інтелект"),("у ШІ","у штучний інтелект"),("до ШІ","до штучного інтелекту"),("згенеровані ШІ","згенеровані штучним інтелектом")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

